import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Tool reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1788437293000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tool-reference" tabindex="-1">Tool reference <a class="header-anchor" href="#tool-reference" aria-label="Permalink to “Tool reference”">​</a></h1><p>All 62 tools: 27 read, 35 write. With <code>WIKIJS_READ_ONLY=true</code> the write tools are not registered at all.</p><p>All 62 are registered unless you say otherwise. <code>WIKIJS_ALLOW_TOOLS</code> and <code>WIKIJS_DENY_TOOLS</code> narrow the list to the ones you want, and <code>WIKIJS_ALLOW_TOOLS=essential</code> selects the 7 marked <strong>essential</strong> below — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>Every tool that addresses a page takes either <code>page_id</code> or <code>path</code> plus <code>locale</code> — the locale is part of a page&#39;s identity and defaults to <code>WIKIJS_LOCALE</code>.</p><p>👤 marks a tool that <strong>asks a person</strong> before it acts, through MCP elicitation — a dialog the model cannot answer on its behalf. Where the client cannot show one it falls back to a two-call <code>confirm_token</code> bound to the exact target, and says which of the two it was. <code>ELICITATION=false</code> takes that fallback deliberately; it never removes the guard. See <a href="/guide/approval">Asking a person</a>.</p><p>Every tool declares all four MCP annotations — <code>readOnlyHint</code>, <code>destructiveHint</code>, <code>idempotentHint</code>, <code>openWorldHint</code>. <code>update_page</code> is deliberately <strong>not</strong> destructive: Wiki.js keeps page history, which is what separates it from the same verb in servers that do not.</p><p>Every tool declares an <code>outputSchema</code> and answers with <code>structuredContent</code> beside the text block, so a client can use a result without parsing prose. The tools that report wiki content carry <code>untrusted: true</code> and <code>source: &quot;wikijs&quot;</code> as fields of that object — page text, titles, descriptions and comments are written by anyone with edit rights.</p><h2 id="read-tools" tabindex="-1">Read tools <a class="header-anchor" href="#read-tools" aria-label="Permalink to “Read tools”">​</a></h2><h3 id="list-pages" tabindex="-1"><code>list_pages</code> <a class="header-anchor" href="#list-pages" aria-label="Permalink to “list_pages”">​</a></h3><p><strong>List pages</strong> — read-only, <strong>essential</strong></p><p>Lists pages with their metadata, newest first by default. The result reports how many pages matched as well as how many are shown, so a short answer is never mistaken for a small wiki. Wiki.js has no offset for this query, so narrow with tags, locale, creator_id or author_id rather than paging. Returns no page content; use get_page for that.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Maximum number of entries to return (default 50). Wiki.js has no offset for page lists, so narrowing by tags, locale or path beats raising this.</td></tr><tr><td><code>tags</code></td><td>string[]</td><td>no</td><td>Only pages carrying all of these tags.</td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>creator_id</code></td><td>integer</td><td>no</td><td>Only pages originally created by this user id.</td></tr><tr><td><code>author_id</code></td><td>integer</td><td>no</td><td>Only pages last edited by this user id.</td></tr><tr><td><code>order_by</code></td><td><code>&quot;TITLE&quot;</code> | <code>&quot;CREATED&quot;</code> | <code>&quot;UPDATED&quot;</code> | <code>&quot;PATH&quot;</code> | <code>&quot;ID&quot;</code></td><td>no</td><td>Sort field (default UPDATED).</td></tr><tr><td><code>direction</code></td><td><code>&quot;ASC&quot;</code> | <code>&quot;DESC&quot;</code></td><td>no</td><td></td></tr></tbody></table><h3 id="get-page" tabindex="-1"><code>get_page</code> <a class="header-anchor" href="#get-page" aria-label="Permalink to “get_page”">​</a></h3><p><strong>Get a page</strong> — read-only, <strong>essential</strong></p><p>Reads one page, addressed by page_id or by path plus locale. Choose a mode: &quot;metadata&quot; for everything but the text, &quot;outline&quot; for the headings only (cheapest way to see what a long page contains), &quot;content&quot; for the source, &quot;rendered&quot; for the HTML. With mode=content, either pass section to get one heading’s worth, or offset and max_chars to read the page in windows — a large page will otherwise be truncated to fit the result budget.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>no</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>path</code></td><td>string</td><td>no</td><td>Page path without a leading slash and without the locale prefix, e.g. &quot;docs/setup&quot;. A browser URL looks like /en/docs/setup — drop the &quot;en/&quot;, it is the locale argument. (Not enforced: &quot;ci/&quot;, &quot;db/&quot; and &quot;qa/&quot; are perfectly good first segments that happen to look like locale codes.)</td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>mode</code></td><td><code>&quot;metadata&quot;</code> | <code>&quot;outline&quot;</code> | <code>&quot;content&quot;</code> | <code>&quot;rendered&quot;</code></td><td>no</td><td>What to return (default &quot;content&quot;).</td></tr><tr><td><code>section</code></td><td>string</td><td>no</td><td>With mode=content: return only the section under this heading, including its subsections. Refuses an ambiguous heading rather than guessing.</td></tr><tr><td><code>offset</code></td><td>integer</td><td>no</td><td>With mode=content: character offset to start at.</td></tr><tr><td><code>max_chars</code></td><td>integer</td><td>no</td><td>With mode=content: how much to return (default 20000).</td></tr></tbody></table><h3 id="search-pages" tabindex="-1"><code>search_pages</code> <a class="header-anchor" href="#search-pages" aria-label="Permalink to “search_pages”">​</a></h3><p><strong>Search pages</strong> — read-only, <strong>essential</strong></p><p>Full-text search — but read this first: on a default Wiki.js the search engine is &quot;Database - Basic&quot;, which only indexes page titles and descriptions, NOT the text inside pages. The result names the active engine so you can tell. If the engine is basic and you are looking for something written inside a page, use grep_pages instead. Results carry no excerpt; follow up with get_page.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>yes</td><td>Search terms.</td></tr><tr><td><code>path</code></td><td>string</td><td>no</td><td>Restrict to this path prefix.</td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Maximum number of entries to return (default 50). Wiki.js has no offset for page lists, so narrowing by tags, locale or path beats raising this.</td></tr></tbody></table><h3 id="grep-pages" tabindex="-1"><code>grep_pages</code> <a class="header-anchor" href="#grep-pages" aria-label="Permalink to “grep_pages”">​</a></h3><p><strong>Search inside page text</strong> — read-only, <strong>essential</strong></p><p>Searches the actual text of pages with a regular expression, by fetching them and matching locally. This exists because Wiki.js’ default search engine does not index page content at all. It is the expensive path — one request per page — so narrow it with path_prefix, tags or locale, and keep max_pages small. Returns matching lines with context, not whole pages.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>pattern</code></td><td>string</td><td>yes</td><td>JavaScript regular expression, matched against page content.</td></tr><tr><td><code>ignore_case</code></td><td>boolean</td><td>no</td><td>Case-insensitive matching (default true).</td></tr><tr><td><code>path_prefix</code></td><td>string</td><td>no</td><td>Only pages whose path starts with this prefix.</td></tr><tr><td><code>tags</code></td><td>string[]</td><td>no</td><td></td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>max_pages</code></td><td>integer</td><td>no</td><td>How many pages to fetch at most (default 60).</td></tr><tr><td><code>context_lines</code></td><td>integer</td><td>no</td><td>Lines of context around each match (default 1).</td></tr></tbody></table><h3 id="get-page-tree" tabindex="-1"><code>get_page_tree</code> <a class="header-anchor" href="#get-page-tree" aria-label="Permalink to “get_page_tree”">​</a></h3><p><strong>Browse the page tree</strong> — read-only, <strong>essential</strong></p><p>Lists the pages and folders directly under a path — the structural view a wiki has and a search does not. mode &quot;ALL&quot; returns both folders and pages, &quot;FOLDERS&quot; only folders, &quot;PAGES&quot; only pages. Wiki.js offers no limit on this query, so a very wide level is truncated to the result budget.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>path</code></td><td>string</td><td>no</td><td>Parent path. Omit for the root of the wiki.</td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>mode</code></td><td><code>&quot;ALL&quot;</code> | <code>&quot;FOLDERS&quot;</code> | <code>&quot;PAGES&quot;</code></td><td>no</td><td></td></tr><tr><td><code>include_ancestors</code></td><td>boolean</td><td>no</td><td>Also return the path from the root down to this level.</td></tr></tbody></table><h3 id="list-page-links" tabindex="-1"><code>list_page_links</code> <a class="header-anchor" href="#list-page-links" aria-label="Permalink to “list_page_links”">​</a></h3><p><strong>List internal links</strong> — read-only</p><p>Returns every page together with the internal links it contains — the wiki’s link graph for one locale. Useful for finding what would break before moving or deleting a page. Wiki.js returns the whole graph at once and offers no filter, so on a large wiki this is truncated.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr></tbody></table><h3 id="list-page-history" tabindex="-1"><code>list_page_history</code> <a class="header-anchor" href="#list-page-history" aria-label="Permalink to “list_page_history”">​</a></h3><p><strong>List a page’s history</strong> — read-only</p><p>Lists the stored versions of a page, newest first, with who changed what and when. This is the one Wiki.js query that really paginates. The version ids here are what get_page_version, diff_page_versions and restore_page_version take.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>no</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>path</code></td><td>string</td><td>no</td><td>Page path without a leading slash and without the locale prefix, e.g. &quot;docs/setup&quot;. A browser URL looks like /en/docs/setup — drop the &quot;en/&quot;, it is the locale argument. (Not enforced: &quot;ci/&quot;, &quot;db/&quot; and &quot;qa/&quot; are perfectly good first segments that happen to look like locale codes.)</td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>page</code></td><td>integer</td><td>no</td><td>Zero-based page of results (default 0).</td></tr><tr><td><code>page_size</code></td><td>integer</td><td>no</td><td>Entries per page (default 50).</td></tr></tbody></table><h3 id="get-page-version" tabindex="-1"><code>get_page_version</code> <a class="header-anchor" href="#get-page-version" aria-label="Permalink to “get_page_version”">​</a></h3><p><strong>Get one stored version</strong> — read-only</p><p>Returns a single historical version of a page, including its full body as it was then. To find out what changed between two versions, diff_page_versions is far cheaper than reading both.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>version_id</code></td><td>integer</td><td>yes</td><td>Version id from list_page_history.</td></tr></tbody></table><h3 id="diff-page-versions" tabindex="-1"><code>diff_page_versions</code> <a class="header-anchor" href="#diff-page-versions" aria-label="Permalink to “diff_page_versions”">​</a></h3><p><strong>Compare two versions</strong> — read-only</p><p>Returns a unified diff between two versions of a page — or between one version and the page as it is now, if to_version is omitted. Answers &quot;what changed here&quot; in one call instead of two full page bodies.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>from_version</code></td><td>integer</td><td>yes</td><td>The older version id, from list_page_history.</td></tr><tr><td><code>to_version</code></td><td>integer</td><td>no</td><td>The newer version id. Omit to compare against the live page.</td></tr><tr><td><code>context_lines</code></td><td>integer</td><td>no</td><td>Unchanged lines shown around each change (default 3).</td></tr></tbody></table><h3 id="get-page-conflict" tabindex="-1"><code>get_page_conflict</code> <a class="header-anchor" href="#get-page-conflict" aria-label="Permalink to “get_page_conflict”">​</a></h3><p><strong>Get the newer version behind a conflict</strong> — read-only</p><p>Returns the version of a page that is newer than the one you read — what update_page points at when it refuses to write. Shows who saved it and when, so the change can be redone on top instead of discarded.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr></tbody></table><h3 id="list-tags" tabindex="-1"><code>list_tags</code> <a class="header-anchor" href="#list-tags" aria-label="Permalink to “list_tags”">​</a></h3><p><strong>List all tags</strong> — read-only</p><p>Every tag in the wiki, with its display title and when it was last used. Tags are the one cross-cutting index a wiki has, so this is often a better starting point than search — feed a tag back into list_pages to see what carries it.</p><p>Takes no parameters.</p><h3 id="search-tags" tabindex="-1"><code>search_tags</code> <a class="header-anchor" href="#search-tags" aria-label="Permalink to “search_tags”">​</a></h3><p><strong>Search tags</strong> — read-only</p><p>Finds tags matching a fragment. Cheaper than list_tags on a wiki with hundreds of them, and the usual way to check what a tag is actually called before filtering list_pages by it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>yes</td><td>Fragment to match against tag names.</td></tr></tbody></table><h3 id="list-assets" tabindex="-1"><code>list_assets</code> <a class="header-anchor" href="#list-assets" aria-label="Permalink to “list_assets”">​</a></h3><p><strong>List assets in a folder</strong> — read-only</p><p>Lists the images and files in one asset folder. Folder 0 is the root. Assets are flat within a folder and Wiki.js has no search across them, so finding one means walking list_asset_folders.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>folder_id</code></td><td>integer,number</td><td>no</td><td>Folder id from list_asset_folders. 0 (default) is the root.</td></tr><tr><td><code>kind</code></td><td><code>&quot;ALL&quot;</code> | <code>&quot;IMAGE&quot;</code> | <code>&quot;BINARY&quot;</code></td><td>no</td><td>Restrict to images or to non-image files.</td></tr></tbody></table><h3 id="list-asset-folders" tabindex="-1"><code>list_asset_folders</code> <a class="header-anchor" href="#list-asset-folders" aria-label="Permalink to “list_asset_folders”">​</a></h3><p><strong>List asset folders</strong> — read-only</p><p>Lists the folders directly under an asset folder. Folder 0 is the root. Wiki.js returns one level at a time, so a deep tree needs one call per level.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>parent_folder_id</code></td><td>integer,number</td><td>no</td><td>Parent folder id. 0 (default) is the root.</td></tr></tbody></table><h3 id="list-comments" tabindex="-1"><code>list_comments</code> <a class="header-anchor" href="#list-comments" aria-label="Permalink to “list_comments”">​</a></h3><p><strong>List comments on a page</strong> — read-only</p><p>Returns the comments on one page, addressed by path and locale — not by page id, which is the one place Wiki.js asks for the path instead. An empty list can also mean comments are switched off for the wiki; get_site_info reports that.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>path</code></td><td>string</td><td>yes</td><td>Page path without a leading slash and without the locale prefix, e.g. &quot;docs/setup&quot;. A browser URL looks like /en/docs/setup — drop the &quot;en/&quot;, it is the locale argument. (Not enforced: &quot;ci/&quot;, &quot;db/&quot; and &quot;qa/&quot; are perfectly good first segments that happen to look like locale codes.)</td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr></tbody></table><h3 id="get-comment" tabindex="-1"><code>get_comment</code> <a class="header-anchor" href="#get-comment" aria-label="Permalink to “get_comment”">​</a></h3><p><strong>Get one comment</strong> — read-only</p><p>Returns a single comment by id, with its source and its rendered HTML.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>comment_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr></tbody></table><h3 id="list-users" tabindex="-1"><code>list_users</code> <a class="header-anchor" href="#list-users" aria-label="Permalink to “list_users”">​</a></h3><p><strong>List users</strong> — read-only</p><p>Lists the wiki’s user accounts. <code>providerKey</code> says how they log in — &quot;local&quot; for a Wiki.js password, anything else for an identity provider. Email addresses are returned because they are the login.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>filter</code></td><td>string</td><td>no</td><td>Substring filter over name and email.</td></tr><tr><td><code>order_by</code></td><td><code>&quot;id&quot;</code> | <code>&quot;email&quot;</code> | <code>&quot;name&quot;</code> | <code>&quot;createdAt&quot;</code> | <code>&quot;updatedAt&quot;</code></td><td>no</td><td></td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Maximum number of entries to return (default 50). Wiki.js has no offset for page lists, so narrowing by tags, locale or path beats raising this.</td></tr></tbody></table><h3 id="search-users" tabindex="-1"><code>search_users</code> <a class="header-anchor" href="#search-users" aria-label="Permalink to “search_users”">​</a></h3><p><strong>Search users</strong> — read-only</p><p>Finds users by name or email. Use it to resolve a person to the id that list_pages (creator_id, author_id) and the group tools take.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>yes</td><td>Name or email fragment.</td></tr></tbody></table><h3 id="get-user" tabindex="-1"><code>get_user</code> <a class="header-anchor" href="#get-user" aria-label="Permalink to “get_user”">​</a></h3><p><strong>Get a user</strong> — read-only</p><p>Full detail for one account, including its group memberships and whether two-factor authentication is active. No credential of any kind is returned — Wiki.js does not expose one.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>user_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr></tbody></table><h3 id="list-groups" tabindex="-1"><code>list_groups</code> <a class="header-anchor" href="#list-groups" aria-label="Permalink to “list_groups”">​</a></h3><p><strong>List groups</strong> — read-only</p><p>Lists the wiki’s groups with how many users each has. Groups marked isSystem are Wiki.js’ own Administrators and Guests — they exist always and should not be deleted.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>filter</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>order_by</code></td><td><code>&quot;id&quot;</code> | <code>&quot;name&quot;</code> | <code>&quot;createdAt&quot;</code> | <code>&quot;updatedAt&quot;</code></td><td>no</td><td></td></tr></tbody></table><h3 id="get-group" tabindex="-1"><code>get_group</code> <a class="header-anchor" href="#get-group" aria-label="Permalink to “get_group”">​</a></h3><p><strong>Get a group</strong> — read-only</p><p>Returns one group with its global permissions, its page rules and its members. This is the authoritative answer to &quot;who can see or edit what&quot; — and it is what update_group needs as its starting point, because that mutation replaces the whole rule set.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>group_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr></tbody></table><h3 id="get-site-info" tabindex="-1"><code>get_site_info</code> <a class="header-anchor" href="#get-site-info" aria-label="Permalink to “get_site_info”">​</a></h3><p><strong>Get site and system information</strong> — read-only</p><p>Version, database, host summary and the site’s own title and description, plus totals for pages, users, groups and tags. The first call to make when something is not behaving — it proves the URL and the API key work at all. Fields describing the host filesystem and database host are deliberately not requested.</p><p>Takes no parameters.</p><h3 id="list-locales" tabindex="-1"><code>list_locales</code> <a class="header-anchor" href="#list-locales" aria-label="Permalink to “list_locales”">​</a></h3><p><strong>List locales</strong> — read-only</p><p>Which locales are installed and which one is the default. Worth checking once per wiki: the locale is part of a page’s identity, and every page tool here falls back to WIKIJS_LOCALE, so a wiki running on &quot;de&quot; needs that set or nothing will be found.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>installed_only</code></td><td>boolean</td><td>no</td><td>Only locales actually installed (default true). Wiki.js lists every locale it could download otherwise — over a hundred.</td></tr></tbody></table><h3 id="get-navigation-tree" tabindex="-1"><code>get_navigation_tree</code> <a class="header-anchor" href="#get-navigation-tree" aria-label="Permalink to “get_navigation_tree”">​</a></h3><p><strong>Get the navigation menu</strong> — read-only</p><p>The sidebar navigation as configured, per locale. This is curated by hand and is not the page tree — get_page_tree is what reflects the pages that actually exist.</p><p>Takes no parameters.</p><h3 id="list-search-engines" tabindex="-1"><code>list_search_engines</code> <a class="header-anchor" href="#list-search-engines" aria-label="Permalink to “list_search_engines”">​</a></h3><p><strong>List search engines</strong> — read-only</p><p>Which search engine this wiki uses. Worth knowing before trusting search_pages: the default &quot;Database - Basic&quot; indexes only titles and descriptions, so nothing written inside a page is searchable until a real engine is configured and the index rebuilt.</p><p>Takes no parameters.</p><h3 id="list-api-keys" tabindex="-1"><code>list_api_keys</code> <a class="header-anchor" href="#list-api-keys" aria-label="Permalink to “list_api_keys”">​</a></h3><p><strong>List API keys</strong> — read-only</p><p>Lists the wiki’s API keys with their expiry and whether they are revoked, plus whether API access is switched on at all. Wiki.js stores only a truncated form of each key and never returns the secret, so nothing here can be used to authenticate.</p><p>Takes no parameters.</p><h3 id="list-storage-targets" tabindex="-1"><code>list_storage_targets</code> <a class="header-anchor" href="#list-storage-targets" aria-label="Permalink to “list_storage_targets”">​</a></h3><p><strong>List storage targets</strong> — read-only</p><p>The configured storage backends — git mirrors, S3 buckets, local file dumps — with their sync status and last error. Credentials in their configuration are redacted.</p><p>Takes no parameters.</p><h2 id="write-tools" tabindex="-1">Write tools <a class="header-anchor" href="#write-tools" aria-label="Permalink to “Write tools”">​</a></h2><h3 id="create-page" tabindex="-1"><code>create_page</code> <a class="header-anchor" href="#create-page" aria-label="Permalink to “create_page”">​</a></h3><p><strong>Create a page</strong> — write, <strong>essential</strong></p><p>Creates a page. The path must not already exist in this locale — Wiki.js answers PageDuplicateCreate otherwise, and update_page is what changes an existing one. The editor decides how content is interpreted, so markdown source needs editor=&quot;markdown&quot;.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>path</code></td><td>string</td><td>yes</td><td>Page path without a leading slash and without the locale prefix, e.g. &quot;docs/setup&quot;. A browser URL looks like /en/docs/setup — drop the &quot;en/&quot;, it is the locale argument. (Not enforced: &quot;ci/&quot;, &quot;db/&quot; and &quot;qa/&quot; are perfectly good first segments that happen to look like locale codes.)</td></tr><tr><td><code>title</code></td><td>string</td><td>yes</td><td>Page title as shown in the wiki.</td></tr><tr><td><code>content</code></td><td>string</td><td>yes</td><td>Full page body, in the page’s content format.</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>Short page description, shown in listings and search results.</td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>tags</code></td><td>string[]</td><td>no</td><td></td></tr><tr><td><code>editor</code></td><td><code>&quot;markdown&quot;</code> | <code>&quot;ckeditor&quot;</code> | <code>&quot;code&quot;</code> | <code>&quot;asciidoc&quot;</code></td><td>no</td><td>Storage format. &quot;markdown&quot; for markdown source, &quot;ckeditor&quot; for rich-text HTML, &quot;code&quot; for raw HTML, &quot;asciidoc&quot; for AsciiDoc.</td></tr><tr><td><code>is_published</code></td><td>boolean</td><td>no</td><td>Publish immediately (default true). False creates a draft.</td></tr><tr><td><code>is_private</code></td><td>boolean</td><td>no</td><td></td></tr></tbody></table><h3 id="update-page" tabindex="-1"><code>update_page</code> <a class="header-anchor" href="#update-page" aria-label="Permalink to “update_page”">​</a></h3><p><strong>Update a page</strong> — write, <strong>essential</strong></p><p>Changes a page. Pass content to replace the whole body, or edits for surgical find-and-replace — each edit’s old_text must appear exactly once, and an ambiguous or missing match is refused rather than applied to the wrong place. Before writing, this checks whether somebody else changed the page since it was read and refuses to clobber them; pass force=true to overwrite deliberately. Metadata fields can be changed on their own, without touching the text. That refusal is a normal result and not an error: it explains what to do — read the page again with get_page, redo the change on top of what is now there, and write. Note that render_page also bumps the page’s timestamp, so calling it between your read and your write triggers the same refusal even though nobody else touched anything.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>no</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>path</code></td><td>string</td><td>no</td><td>Page path without a leading slash and without the locale prefix, e.g. &quot;docs/setup&quot;. A browser URL looks like /en/docs/setup — drop the &quot;en/&quot;, it is the locale argument. (Not enforced: &quot;ci/&quot;, &quot;db/&quot; and &quot;qa/&quot; are perfectly good first segments that happen to look like locale codes.)</td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>content</code></td><td>string</td><td>no</td><td>Replacement body. Mutually exclusive with edits.</td></tr><tr><td><code>edits</code></td><td>object[]</td><td>no</td><td>Find-and-replace edits. Mutually exclusive with content.</td></tr><tr><td><code>title</code></td><td>string</td><td>no</td><td>Page title as shown in the wiki.</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>Short page description, shown in listings and search results.</td></tr><tr><td><code>tags</code></td><td>string[]</td><td>no</td><td>Replaces the whole tag list, it is not merged.</td></tr><tr><td><code>is_published</code></td><td>boolean</td><td>no</td><td></td></tr><tr><td><code>is_private</code></td><td>boolean</td><td>no</td><td></td></tr><tr><td><code>editor</code></td><td><code>&quot;markdown&quot;</code> | <code>&quot;ckeditor&quot;</code> | <code>&quot;code&quot;</code> | <code>&quot;asciidoc&quot;</code></td><td>no</td><td>Storage format. &quot;markdown&quot; for markdown source, &quot;ckeditor&quot; for rich-text HTML, &quot;code&quot; for raw HTML, &quot;asciidoc&quot; for AsciiDoc.</td></tr><tr><td><code>expected_updated_at</code></td><td>string</td><td>no</td><td>The updatedAt value you saw when you read this page. Normally unnecessary — a previous get_page in this session is remembered automatically — but it makes the concurrent-edit check work without one.</td></tr><tr><td><code>force</code></td><td>boolean</td><td>no</td><td>Write even though the page changed since you read it. Overwrites the other person’s edit.</td></tr></tbody></table><h3 id="move-page-👤" tabindex="-1"><code>move_page</code> 👤 <a class="header-anchor" href="#move-page-👤" aria-label="Permalink to “move_page 👤”">​</a></h3><p><strong>Move or rename a page</strong> — write</p><p>Moves a page to another path, another locale, or both. Internal links pointing at the old path are NOT rewritten by Wiki.js — check list_page_links first if that matters.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>no</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>path</code></td><td>string</td><td>no</td><td>Page path without a leading slash and without the locale prefix, e.g. &quot;docs/setup&quot;. A browser URL looks like /en/docs/setup — drop the &quot;en/&quot;, it is the locale argument. (Not enforced: &quot;ci/&quot;, &quot;db/&quot; and &quot;qa/&quot; are perfectly good first segments that happen to look like locale codes.)</td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>destination_path</code></td><td>string</td><td>yes</td><td>Page path without a leading slash and without the locale prefix, e.g. &quot;docs/setup&quot;. A browser URL looks like /en/docs/setup — drop the &quot;en/&quot;, it is the locale argument. (Not enforced: &quot;ci/&quot;, &quot;db/&quot; and &quot;qa/&quot; are perfectly good first segments that happen to look like locale codes.)</td></tr><tr><td><code>destination_locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="delete-page-👤" tabindex="-1"><code>delete_page</code> 👤 <a class="header-anchor" href="#delete-page-👤" aria-label="Permalink to “delete_page 👤”">​</a></h3><p><strong>Delete a page</strong> — write, destructive</p><p>Deletes a page and its history. Wiki.js has no trash — this cannot be undone from here. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>no</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>path</code></td><td>string</td><td>no</td><td>Page path without a leading slash and without the locale prefix, e.g. &quot;docs/setup&quot;. A browser URL looks like /en/docs/setup — drop the &quot;en/&quot;, it is the locale argument. (Not enforced: &quot;ci/&quot;, &quot;db/&quot; and &quot;qa/&quot; are perfectly good first segments that happen to look like locale codes.)</td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="convert-page-editor-👤" tabindex="-1"><code>convert_page_editor</code> 👤 <a class="header-anchor" href="#convert-page-editor-👤" aria-label="Permalink to “convert_page_editor 👤”">​</a></h3><p><strong>Convert a page to another editor</strong> — write</p><p>Changes the storage format of a page. Wiki.js does not translate the body — converting markdown to &quot;code&quot; leaves the markdown source as raw HTML text. Use it to correct a page created with the wrong editor, not to reformat one.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>no</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>path</code></td><td>string</td><td>no</td><td>Page path without a leading slash and without the locale prefix, e.g. &quot;docs/setup&quot;. A browser URL looks like /en/docs/setup — drop the &quot;en/&quot;, it is the locale argument. (Not enforced: &quot;ci/&quot;, &quot;db/&quot; and &quot;qa/&quot; are perfectly good first segments that happen to look like locale codes.)</td></tr><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale code. Defaults to WIKIJS_LOCALE. The locale is part of a page’s identity.</td></tr><tr><td><code>editor</code></td><td><code>&quot;markdown&quot;</code> | <code>&quot;ckeditor&quot;</code> | <code>&quot;code&quot;</code> | <code>&quot;asciidoc&quot;</code></td><td>yes</td><td>Storage format. &quot;markdown&quot; for markdown source, &quot;ckeditor&quot; for rich-text HTML, &quot;code&quot; for raw HTML, &quot;asciidoc&quot; for AsciiDoc.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="restore-page-version-👤" tabindex="-1"><code>restore_page_version</code> 👤 <a class="header-anchor" href="#restore-page-version-👤" aria-label="Permalink to “restore_page_version 👤”">​</a></h3><p><strong>Restore an earlier version</strong> — write, destructive</p><p>Rolls a page back to a stored version. The current content is not lost — it becomes another entry in the history — but the live page is replaced. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>version_id</code></td><td>integer</td><td>yes</td><td>Version id from list_page_history.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="update-tag-👤" tabindex="-1"><code>update_tag</code> 👤 <a class="header-anchor" href="#update-tag-👤" aria-label="Permalink to “update_tag 👤”">​</a></h3><p><strong>Rename a tag</strong> — write, destructive</p><p>Changes a tag’s name or display title across every page carrying it. Renaming affects all of them at once, which is the point and also the risk, so it needs a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>tag_id</code></td><td>integer</td><td>yes</td><td>Tag id from list_tags.</td></tr><tr><td><code>tag</code></td><td>string</td><td>yes</td><td>New tag name.</td></tr><tr><td><code>title</code></td><td>string</td><td>yes</td><td>New display title.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="delete-tag-👤" tabindex="-1"><code>delete_tag</code> 👤 <a class="header-anchor" href="#delete-tag-👤" aria-label="Permalink to “delete_tag 👤”">​</a></h3><p><strong>Delete a tag</strong> — write, destructive</p><p>Removes a tag from the wiki and from every page that carries it. The pages themselves are untouched. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>tag_id</code></td><td>integer</td><td>yes</td><td>Tag id from list_tags.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="upload-asset" tabindex="-1"><code>upload_asset</code> <a class="header-anchor" href="#upload-asset" aria-label="Permalink to “upload_asset”">​</a></h3><p><strong>Upload a file</strong> — write</p><p>Uploads an image or file to an asset folder, so it can be embedded in a page. Content is passed base64-encoded and the content type is derived from the extension. SVG, HTML and XML are refused: Wiki.js serves assets from the wiki’s own origin, so those can carry script that runs for every reader. Note that Wiki.js 2.x has no GraphQL mutation for uploads at all — this uses the editor’s own route, which is undocumented and could change in a future Wiki.js release.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>filename</code></td><td>string</td><td>yes</td><td>File name including its extension, e.g. &quot;diagram.png&quot;.</td></tr><tr><td><code>content_base64</code></td><td>string</td><td>yes</td><td>File contents, base64-encoded.</td></tr><tr><td><code>folder_id</code></td><td>integer,number</td><td>no</td><td>Target folder id. 0 (default) is the root.</td></tr></tbody></table><h3 id="create-asset-folder" tabindex="-1"><code>create_asset_folder</code> <a class="header-anchor" href="#create-asset-folder" aria-label="Permalink to “create_asset_folder”">​</a></h3><p><strong>Create an asset folder</strong> — write</p><p>Creates a folder in the asset store. The slug is what appears in the URL of every file inside it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>parent_folder_id</code></td><td>integer,number</td><td>no</td><td>Parent folder id. 0 (default) is the root.</td></tr><tr><td><code>slug</code></td><td>string</td><td>yes</td><td>URL segment for the folder.</td></tr><tr><td><code>name</code></td><td>string</td><td>no</td><td>Display name (defaults to the slug).</td></tr></tbody></table><h3 id="rename-asset-👤" tabindex="-1"><code>rename_asset</code> 👤 <a class="header-anchor" href="#rename-asset-👤" aria-label="Permalink to “rename_asset 👤”">​</a></h3><p><strong>Rename a file</strong> — write</p><p>Renames an asset. Pages embedding it by its old URL will break — Wiki.js does not rewrite them.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>asset_id</code></td><td>integer</td><td>yes</td><td>Asset id from list_assets.</td></tr><tr><td><code>filename</code></td><td>string</td><td>yes</td><td>New file name, including extension.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="delete-asset-👤" tabindex="-1"><code>delete_asset</code> 👤 <a class="header-anchor" href="#delete-asset-👤" aria-label="Permalink to “delete_asset 👤”">​</a></h3><p><strong>Delete a file</strong> — write, destructive</p><p>Deletes an asset permanently. Any page embedding it will show a broken image or a dead link. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>asset_id</code></td><td>integer</td><td>yes</td><td>Asset id from list_assets.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="create-comment" tabindex="-1"><code>create_comment</code> <a class="header-anchor" href="#create-comment" aria-label="Permalink to “create_comment”">​</a></h3><p><strong>Post a comment</strong> — write</p><p>Posts a comment on a page, optionally as a reply to another. The comment is attributed to the account the API key belongs to, which is usually a service account rather than a person — say so in the text if that matters.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>yes</td><td>Page id the comment belongs to.</td></tr><tr><td><code>content</code></td><td>string</td><td>yes</td><td>Comment body, in markdown.</td></tr><tr><td><code>reply_to</code></td><td>integer</td><td>no</td><td>Comment id this replies to.</td></tr></tbody></table><h3 id="update-comment-👤" tabindex="-1"><code>update_comment</code> 👤 <a class="header-anchor" href="#update-comment-👤" aria-label="Permalink to “update_comment 👤”">​</a></h3><p><strong>Edit a comment</strong> — write, destructive</p><p>Replaces the body of a comment. Wiki.js keeps no history for comments, so the previous text is gone.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>comment_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>content</code></td><td>string</td><td>yes</td><td>Comment body, in markdown.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="delete-comment-👤" tabindex="-1"><code>delete_comment</code> 👤 <a class="header-anchor" href="#delete-comment-👤" aria-label="Permalink to “delete_comment 👤”">​</a></h3><p><strong>Delete a comment</strong> — write, destructive</p><p>Removes a comment permanently. Replies to it are not removed with it. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>comment_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="create-user-👤" tabindex="-1"><code>create_user</code> 👤 <a class="header-anchor" href="#create-user-👤" aria-label="Permalink to “create_user 👤”">​</a></h3><p><strong>Create a user</strong> — write</p><p>Creates an account. For a local account supply a password, or set send_welcome_email so Wiki.js mails an invitation instead. Groups are given by id — list_groups has them, and an account in no group can log in but see nothing.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>email</code></td><td>string</td><td>yes</td><td>Email address, which is also the login for local accounts.</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Display name.</td></tr><tr><td><code>password</code></td><td>string</td><td>no</td><td>Initial password for a local account. Never echoed back by this server.</td></tr><tr><td><code>provider_key</code></td><td>string</td><td>no</td><td>Authentication provider (default &quot;local&quot;).</td></tr><tr><td><code>groups</code></td><td>integer[]</td><td>no</td><td>Group ids to put the account in.</td></tr><tr><td><code>must_change_password</code></td><td>boolean</td><td>no</td><td></td></tr><tr><td><code>send_welcome_email</code></td><td>boolean</td><td>no</td><td></td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="update-user-👤" tabindex="-1"><code>update_user</code> 👤 <a class="header-anchor" href="#update-user-👤" aria-label="Permalink to “update_user 👤”">​</a></h3><p><strong>Update a user</strong> — write, destructive</p><p>Changes an account’s details or its group membership. The groups list replaces the existing one rather than adding to it — use assign_user_to_group for a single addition.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>user_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>email</code></td><td>string</td><td>no</td><td>Email address, which is also the login for local accounts.</td></tr><tr><td><code>name</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>groups</code></td><td>integer[]</td><td>no</td><td>Replaces the whole group list.</td></tr><tr><td><code>location</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>job_title</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="delete-user-👤" tabindex="-1"><code>delete_user</code> 👤 <a class="header-anchor" href="#delete-user-👤" aria-label="Permalink to “delete_user 👤”">​</a></h3><p><strong>Delete a user</strong> — write, destructive</p><p>Removes an account. Wiki.js needs somebody to inherit the pages it authored, so replace_with_user_id is required — pass the id of the account that should own them afterwards. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>user_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>replace_with_user_id</code></td><td>integer</td><td>yes</td><td>Account that inherits the deleted user’s pages.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="set-user-active-👤" tabindex="-1"><code>set_user_active</code> 👤 <a class="header-anchor" href="#set-user-active-👤" aria-label="Permalink to “set_user_active 👤”">​</a></h3><p><strong>Activate or deactivate a user</strong> — write</p><p>Switches an account on or off. A deactivated account keeps its pages and groups but cannot sign in — the reversible alternative to delete_user. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>user_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>active</code></td><td>boolean</td><td>yes</td><td>True to activate, false to deactivate.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="verify-user-👤" tabindex="-1"><code>verify_user</code> 👤 <a class="header-anchor" href="#verify-user-👤" aria-label="Permalink to “verify_user 👤”">​</a></h3><p><strong>Mark a user as verified</strong> — write</p><p>Marks an account’s email as verified, which is otherwise done by the user clicking a link. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>user_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="set-user-tfa-👤" tabindex="-1"><code>set_user_tfa</code> 👤 <a class="header-anchor" href="#set-user-tfa-👤" aria-label="Permalink to “set_user_tfa 👤”">​</a></h3><p><strong>Turn two-factor authentication on or off</strong> — write</p><p>Switches an account’s second factor. Turning it OFF weakens that account and is the reason this is gated; turning it on forces the user to enrol at their next sign-in. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>user_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>enabled</code></td><td>boolean</td><td>yes</td><td>True to require 2FA, false to remove it.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="reset-user-password-👤" tabindex="-1"><code>reset_user_password</code> 👤 <a class="header-anchor" href="#reset-user-password-👤" aria-label="Permalink to “reset_user_password 👤”">​</a></h3><p><strong>Reset a user’s password</strong> — write, destructive</p><p>Starts Wiki.js’ own password reset for a local account, which emails the user a link. No password is chosen or returned here. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>user_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="create-group" tabindex="-1"><code>create_group</code> <a class="header-anchor" href="#create-group" aria-label="Permalink to “create_group”">​</a></h3><p><strong>Create a group</strong> — write</p><p>Creates an empty group. It starts with no permissions and no page rules, so it grants nothing until update_group is called.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Group name.</td></tr></tbody></table><h3 id="update-group-👤" tabindex="-1"><code>update_group</code> 👤 <a class="header-anchor" href="#update-group-👤" aria-label="Permalink to “update_group 👤”">​</a></h3><p><strong>Update a group’s permissions</strong> — write, destructive</p><p>Replaces a group’s name, permissions, page rules and login redirect wholesale — this is not a partial update, and omitting a rule deletes it, just as omitting redirect_on_login resets it to &quot;/&quot;. Read the group with get_group first and send back the full set with your change applied. Requires a confirmation token, because this is the call that decides who can read and edit the wiki.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>group_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td></td></tr><tr><td><code>permissions</code></td><td>string[]</td><td>yes</td><td>Global permissions, e.g. [&quot;read:pages&quot;,&quot;write:pages&quot;]. Replaces the existing list.</td></tr><tr><td><code>page_rules</code></td><td>object[]</td><td>yes</td><td>Complete page rule set. Replaces the existing one.</td></tr><tr><td><code>redirect_on_login</code></td><td>string</td><td>no</td><td>Where members land after signing in (default &quot;/&quot;).</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="delete-group-👤" tabindex="-1"><code>delete_group</code> 👤 <a class="header-anchor" href="#delete-group-👤" aria-label="Permalink to “delete_group 👤”">​</a></h3><p><strong>Delete a group</strong> — write, destructive</p><p>Removes a group. Its members keep their accounts but lose whatever access the group gave them. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>group_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="assign-user-to-group-👤" tabindex="-1"><code>assign_user_to_group</code> 👤 <a class="header-anchor" href="#assign-user-to-group-👤" aria-label="Permalink to “assign_user_to_group 👤”">​</a></h3><p><strong>Add a user to a group</strong> — write</p><p>Adds one account to one group, leaving its other memberships alone — the additive counterpart to update_user’s groups list. Requires a confirmation token, because a group is what grants access.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>group_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>user_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="unassign-user-from-group-👤" tabindex="-1"><code>unassign_user_from_group</code> 👤 <a class="header-anchor" href="#unassign-user-from-group-👤" aria-label="Permalink to “unassign_user_from_group 👤”">​</a></h3><p><strong>Remove a user from a group</strong> — write, destructive</p><p>Takes one account out of one group. Requires a confirmation token — removing somebody from their only group leaves them able to sign in and see nothing.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>group_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>user_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="revoke-api-key-👤" tabindex="-1"><code>revoke_api_key</code> 👤 <a class="header-anchor" href="#revoke-api-key-👤" aria-label="Permalink to “revoke_api_key 👤”">​</a></h3><p><strong>Revoke an API key</strong> — write, destructive</p><p>Revokes an API key immediately and for good — Wiki.js has no way to un-revoke one. Note that this can revoke the key this server is using, which would cut its own connection. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>key_id</code></td><td>integer</td><td>yes</td><td>Key id from list_api_keys.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="set-api-state-👤" tabindex="-1"><code>set_api_state</code> 👤 <a class="header-anchor" href="#set-api-state-👤" aria-label="Permalink to “set_api_state 👤”">​</a></h3><p><strong>Turn the API on or off</strong> — write, destructive</p><p>Switches Wiki.js’ whole API on or off. Turning it off disables every API key at once, including this server’s — after which the only way back is the web administration UI. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>boolean</td><td>yes</td><td>True to enable the API, false to disable it.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="render-page" tabindex="-1"><code>render_page</code> <a class="header-anchor" href="#render-page" aria-label="Permalink to “render_page”">​</a></h3><p><strong>Re-render a page</strong> — write</p><p>Forces Wiki.js to regenerate one page’s HTML from its source. The fix for a page whose rendering is stale after a theme or renderer change. Changes no content and cannot lose anything. It does, however, bump the page’s updatedAt — and update_page compares that against when you last read the page, to catch somebody else saving in between. So a render between your read and your write makes update_page refuse <em>your own</em> next write, saying the page changed after you read it. If that happens, call get_page again and then write; nothing was lost. Better still, render after writing rather than before.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>integer</td><td>yes</td><td>Numeric Wiki.js id.</td></tr></tbody></table><h3 id="flush-page-cache" tabindex="-1"><code>flush_page_cache</code> <a class="header-anchor" href="#flush-page-cache" aria-label="Permalink to “flush_page_cache”">​</a></h3><p><strong>Flush the page cache</strong> — write</p><p>Drops Wiki.js’ rendered-page cache for the whole wiki. Nothing is lost, but every page has to be rendered again on first access, so a busy instance gets slower for a while.</p><p>Takes no parameters.</p><h3 id="rebuild-page-tree" tabindex="-1"><code>rebuild_page_tree</code> <a class="header-anchor" href="#rebuild-page-tree" aria-label="Permalink to “rebuild_page_tree”">​</a></h3><p><strong>Rebuild the page tree</strong> — write</p><p>Recomputes the folder structure Wiki.js derives from page paths. The repair for a navigation tree that disagrees with the pages actually present, usually after a bulk import or a database edit. Page content is untouched, but it walks every page and can take minutes.</p><p>Takes no parameters.</p><h3 id="rebuild-search-index" tabindex="-1"><code>rebuild_search_index</code> <a class="header-anchor" href="#rebuild-search-index" aria-label="Permalink to “rebuild_search_index”">​</a></h3><p><strong>Rebuild the search index</strong> — write</p><p>Reindexes every page in the active search engine. Required once after switching away from &quot;Database - Basic&quot;, because the new engine starts empty and search silently returns nothing until this runs. On the basic engine it does nothing. Search results may be incomplete while it runs, and it can take minutes on a large wiki.</p><p>Takes no parameters.</p><h3 id="purge-page-history-👤" tabindex="-1"><code>purge_page_history</code> 👤 <a class="header-anchor" href="#purge-page-history-👤" aria-label="Permalink to “purge_page_history 👤”">​</a></h3><p><strong>Purge old page versions</strong> — write, destructive</p><p>Deletes stored page versions older than a cutoff, across the whole wiki. The versions are gone permanently — this is the one maintenance operation that destroys data. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>older_than</code></td><td><code>&quot;P1D&quot;</code> | <code>&quot;P1M&quot;</code> | <code>&quot;P3M&quot;</code> | <code>&quot;P6M&quot;</code> | <code>&quot;P1Y&quot;</code> | <code>&quot;P2Y&quot;</code> | <code>&quot;P3Y&quot;</code></td><td>yes</td><td>ISO-8601 duration cutoff, as Wiki.js’ own admin UI offers: P1D (a day), P1M, P3M, P6M, P1Y, P2Y, P3Y. Versions older than this are deleted.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table><h3 id="migrate-pages-locale-👤" tabindex="-1"><code>migrate_pages_locale</code> 👤 <a class="header-anchor" href="#migrate-pages-locale-👤" aria-label="Permalink to “migrate_pages_locale 👤”">​</a></h3><p><strong>Move every page to another locale</strong> — write, destructive</p><p>Moves all pages from one locale to another, across the whole wiki. The usual reason is a wiki set up under the wrong locale code. Every page path changes, so every external link into the wiki breaks. Requires a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>source_locale</code></td><td>string</td><td>yes</td><td>Locale to move pages out of.</td></tr><tr><td><code>target_locale</code></td><td>string</td><td>yes</td><td>Locale to move pages into.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from this tool’s previous, unconfirmed call. Omit it to receive one.</td></tr></tbody></table>`,257)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};